const BulkDrawer=({kind,count,selection,operations,supervisors,onClose,onDone}:any)=>{const [form,setForm]=useState({operationId:'',supervisorId:'',effectiveAt:today(),reason:'Actualización masiva de dotación.'}),[validSupervisors,setValidSupervisors]=useState<any[]>(supervisors),[preview,setPreview]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);const api=kind==='SUPERVISOR'?organizationApi.bulkSupervisor:organizationApi.bulkMove;useEffect(()=>{if(kind!=='OPERATION'||!form.operationId)return setValidSupervisors(supervisors);let active=true;void organizationApi.supervisors(form.operationId).then(result=>active&&setValidSupervisors(result.supervisors||[])).catch(reason=>active&&setError(errorText(reason)));return()=>{active=false}},[form.operationId,kind,supervisors]);const run=async(dryRun:boolean)=>{try{setBusy(true);setError('');const result=await api({...form,selection,dryRun});if(dryRun)setPreview(result.preview);else await onDone(result)}catch(reason){setError(errorText(reason))}finally{setBusy(false)}};return <Drawer eyebrow="ACCIÓN MASIVA" title={kind==='SUPERVISOR'?'Cambiar supervisor':'Mover dotación'} subtitle={`${count} colaboradores seleccionados`} onClose={onClose} footer={<><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button variant="secondary" loading={busy&&!preview} onClick={()=>run(true)}>Validar</Button><Button loading={busy&&!!preview} disabled={!preview?.valid} onClick={()=>run(false)}>Confirmar cambios</Button></>}><div className="cm-form-stack">{error&&<ErrorState description={error}/>} {kind==='OPERATION'&&<Field required label="Empresa / campaña destino"><Select value={form.operationId} onChange={event=>{setForm({...form,operationId:event.target.value,supervisorId:''});setPreview(null)}}><option value="">Seleccionar destino</option>{operations.filter((operation:any)=>operation.status==='ACTIVA').map((operation:any)=><option key={operation.id} value={operation.id}>{operation.companyName} / {operation.name}</option>)}</Select></Field>}<Field label="Supervisor destino"><Select value={form.supervisorId} onChange={event=>{setForm({...form,supervisorId:event.target.value});setPreview(null)}}><option value="">Sin supervisor</option>{validSupervisors.map((user:any)=><option key={user.id} value={user.id}>{user.name}</option>)}</Select></Field><Field required label="Fecha efectiva"><DateInput value={form.effectiveAt} onChange={event=>{setForm({...form,effectiveAt:event.target.value});setPreview(null)}}/></Field><Field required label="Motivo"><Textarea value={form.reason} onChange={event=>setForm({...form,reason:event.target.value})}/></Field>{preview&&<ReviewPanel preview={preview} operation={operations.find((operation:any)=>operation.id===form.operationId)?.name||'Asignación actual'} supervisorCount={form.supervisorId?1:0} effectiveAt={form.effectiveAt}/>}</div></Drawer>};

const IssuesDrawer=({issues,operations,supervisors,canManage,onClose,onDone}:any)=>{
 const groups=Object.values(issues.reduce((result:any,issue:any)=>{const key=`${issue.type}|${issue.supervisorId||''}|${issue.campaignName||''}`;result[key]||={key,type:issue.type,supervisorName:issue.supervisorName,campaignName:issue.campaignName,cause:issue.cause,items:[]};result[key].items.push(issue);return result},{})) as any[];
 const activeOperations=useMemo(()=>operations.filter((operation:any)=>operation.status==='ACTIVA'),[operations]);
 const companies=useMemo(()=>[...new Map(activeOperations.map((operation:any)=>[operation.companyId,{id:operation.companyId,name:operation.companyName}])).values()] as any[],[activeOperations]);
 const [selected,setSelected]=useState<string[]>([]),[companyId,setCompanyId]=useState(''),[operationId,setOperationId]=useState(''),[supervisorId,setSupervisorId]=useState(''),[effectiveAt,setEffectiveAt]=useState(today()),[validSupervisors,setValidSupervisors]=useState<any[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const minimumEffectiveAt=useMemo(()=>issues.filter((issue:any)=>selected.includes(issue.advisorId)).map((issue:any)=>String(issue.startDate||'')).filter(Boolean).sort().at(-1)||today(),[issues,selected]);
 useEffect(()=>{if(effectiveAt<minimumEffectiveAt)setEffectiveAt(minimumEffectiveAt)},[effectiveAt,minimumEffectiveAt]);
 useEffect(()=>{if(!operationId){setValidSupervisors([]);return}let active=true;setError('');void organizationApi.supervisors(operationId).then(result=>active&&setValidSupervisors(result.supervisors||[])).catch(reason=>active&&setError(errorText(reason)));return()=>{active=false}},[operationId]);
 const resolve=async()=>{if(!selected.length)return setError('Selecciona al menos una persona.');if(!operationId)return setError('Selecciona la empresa y la campaña destino.');try{setBusy(true);setError('');await organizationApi.resolve({advisorIds:selected,operationId,supervisorId,effectiveAt,reason:'Resolución validada de inconsistencia.'});await onDone()}catch(reason){setError(errorText(reason))}finally{setBusy(false)}};
 const choose=(issue:any,checked:boolean)=>setSelected(items=>checked?[...new Set([...items,issue.advisorId])]:items.filter(id=>id!==issue.advisorId));
 return <Drawer eyebrow="CALIDAD DE DATOS" title="Resolver asignaciones" subtitle={`${issues.length} inconsistencias detectadas`} onClose={onClose} footer={canManage?<><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button loading={busy} disabled={!selected.length||!operationId||effectiveAt<minimumEffectiveAt} onClick={resolve}>Aplicar corrección</Button></>:undefined}><div className="cm-form-stack">
  {error&&<ErrorState description={error}/>}
  {canManage&&<Card className="cm-issues-destination"><CardHeader title="Destino de la corrección" description={selected.length?`${selected.length} personas seleccionadas`:'Selecciona personas en los grupos inferiores'}/><CardContent className="cm-form-stack"><Field required label="Empresa"><Select value={companyId} onChange={event=>{setCompanyId(event.target.value);setOperationId('');setSupervisorId('');setError('')}}><option value="">Seleccionar empresa</option>{companies.map((company:any)=><option key={company.id} value={company.id}>{company.name}</option>)}</Select></Field><Field required label="Campaña"><Select disabled={!companyId} value={operationId} onChange={event=>{setOperationId(event.target.value);setSupervisorId('');setError('')}}><option value="">Seleccionar campaña</option>{activeOperations.filter((operation:any)=>operation.companyId===companyId).map((operation:any)=><option key={operation.id} value={operation.id}>{operation.name}</option>)}</Select></Field><Field label="Supervisor"><Select disabled={!operationId} value={supervisorId} onChange={event=>setSupervisorId(event.target.value)}><option value="">Sin supervisor</option>{validSupervisors.map((user:any)=><option key={user.id} value={user.id}>{user.name}</option>)}</Select></Field><Field required label="Fecha efectiva"><DateInput min={minimumEffectiveAt} value={effectiveAt} onChange={event=>setEffectiveAt(event.target.value)}/></Field>{selected.length>0&&minimumEffectiveAt>today()&&<p className="cm-helper">La fecha se ajustó a {minimumEffectiveAt} para no solapar el historial existente.</p>}</CardContent></Card>}
  {groups.map(group=><Card key={group.key}><CardHeader title={`${group.type} · ${group.items.length}`} description={[group.supervisorName,group.campaignName].filter(Boolean).join(' / ')||group.cause} action={canManage?<Button size="sm" variant="ghost" onClick={()=>setSelected(items=>[...new Set([...items,...group.items.map((item:any)=>item.advisorId)])])}>Seleccionar grupo</Button>:undefined}/><CardContent className="cm-issue-list">{group.items.slice(0,10).map((issue:any)=><Checkbox key={issue.id} disabled={!canManage} label={issue.advisorName||issue.advisorId} checked={selected.includes(issue.advisorId)} onChange={event=>choose(issue,event.target.checked)}/>)}{group.items.length>10&&<p>y {group.items.length-10} más…</p>}</CardContent></Card>)}
  {!groups.length&&<EmptyState title="Sin inconsistencias" description="La estructura y las asignaciones activas son coherentes."/>}
 </div></Drawer>
};

const ActionDialog=({state,operations,onClose,onDone}:any)=>{const [form,setForm]=useState({destinationOperationId:'',destinationSupervisorId:'',effectiveAt:today(),reason:''}),[validSupervisors,setValidSupervisors]=useState<any[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('');const isClose=state.kind==='CLOSE',isDelete=state.kind==='DELETE',requiresDestination=isClose&&Number(state.item.advisorCount)>0;useEffect(()=>{if(!form.destinationOperationId)return setValidSupervisors([]);let active=true;void organizationApi.supervisors(form.destinationOperationId).then(result=>active&&setValidSupervisors(result.supervisors||[])).catch(reason=>active&&setError(errorText(reason)));return()=>{active=false}},[form.destinationOperationId]);const apply=async()=>{try{setBusy(true);setError('');if(isClose){await organizationApi.close(state.item.id,form);await onDone('Campaña cerrada y dotación reasignada.')}else if(isDelete){await organizationApi.remove(state.item.id);await onDone('Campaña vacía eliminada.')}else{await organizationApi.reverse(state.item.id,{effectiveAt:form.effectiveAt,reason:form.reason||`Reversión de ${state.item.id}`});await onDone('Movimiento revertido con trazabilidad.')}}catch(reason){setError(errorText(reason))}finally{setBusy(false)}};return <Modal open title={isClose?'Cerrar campaña':isDelete?'Eliminar campaña':'Revertir movimiento'} description={isClose?`${state.item.name} tiene ${state.item.advisorCount||0} colaboradores activos.`:isDelete?'Sólo se eliminará si no tiene referencias históricas.':'Se creará un movimiento inverso; el original se conservará.'} tone={isDelete?'danger':'confirm'} onClose={onClose} footer={<><Button variant="secondary" onClick={onClose}>Cancelar</Button><Button variant={isDelete?'danger':'primary'} loading={busy} disabled={requiresDestination&&!form.destinationOperationId} onClick={apply}>{isClose?'Cerrar campaña':isDelete?'Eliminar definitivamente':'Crear reversión'}</Button></>}><div className="cm-form-stack">{error&&<ErrorState description={error}/>} {requiresDestination&&<><Field required label="Empresa / campaña destino"><Select value={form.destinationOperationId} onChange={event=>setForm({...form,destinationOperationId:event.target.value,destinationSupervisorId:''})}><option value="">Seleccionar destino</option>{operations.filter((operation:any)=>operation.status==='ACTIVA'&&operation.id!==state.item.id).map((operation:any)=><option key={operation.id} value={operation.id}>{operation.companyName} / {operation.name}</option>)}</Select></Field><Field label="Supervisor destino"><Select value={form.destinationSupervisorId} onChange={event=>setForm({...form,destinationSupervisorId:event.target.value})}><option value="">Sin supervisor</option>{validSupervisors.map((user:any)=><option key={user.id} value={user.id}>{user.name}</option>)}</Select></Field></>} {!isDelete&&<><Field required label="Fecha efectiva"><DateInput value={form.effectiveAt} onChange={event=>setForm({...form,effectiveAt:event.target.value})}/></Field><Field label="Motivo"><Textarea value={form.reason} onChange={event=>setForm({...form,reason:event.target.value})}/></Field></>}</div></Modal>};
